import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Product Backlog","description":"Prioritised backlog of pending features, technical debt, and long-term ideas. Completed items are archived in changelog.md. AI agents should read this file to understand what features are planned but not yet started.\\n","frontmatter":{"isInternal":true,"type":"Planning","title":"Product Backlog","description":"Prioritised backlog of pending features, technical debt, and long-term ideas. Completed items are archived in changelog.md. AI agents should read this file to understand what features are planned but not yet started.\\n","tags":["planning","backlog","roadmap","features"]},"headers":[],"relativePath":"planning/features_backlog.md","filePath":"planning/features_backlog.md"}'),i={name:"planning/features_backlog.md"};function n(s,e,l,d,c,g){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="product-backlog-sanjeev-ai" tabindex="-1">Product Backlog: Sanjeev AI <a class="header-anchor" href="#product-backlog-sanjeev-ai" aria-label="Permalink to &quot;Product Backlog: Sanjeev AI&quot;">​</a></h1><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>AI Instruction:</strong> This file contains ONLY pending work. If an item is marked as done or already exists in the codebase, it belongs in <a href="./changelog.html">changelog.md</a>, not here. Do NOT re-implement features listed in the changelog.</p></div><hr><h2 id="p0-—-next-priority" tabindex="-1">P0 — Next Priority <a class="header-anchor" href="#p0-—-next-priority" aria-label="Permalink to &quot;P0 — Next Priority&quot;">​</a></h2><h3 id="centralized-docs-portal" tabindex="-1">Centralized Docs Portal <a class="header-anchor" href="#centralized-docs-portal" aria-label="Permalink to &quot;Centralized Docs Portal&quot;">​</a></h3><ul><li>Set up a new standalone Firebase project dedicated to the Docs Portal.</li><li>Implement a project switcher UI to toggle documentation between different repositories/projects.</li><li>Completely decouple Docs Portal deployment from the main <code>sanjeev-ai-staging</code> pipeline so documentation can be deployed immediately after planning phases.</li></ul><h3 id="support-readiness" tabindex="-1">Support Readiness <a class="header-anchor" href="#support-readiness" aria-label="Permalink to &quot;Support Readiness&quot;">​</a></h3><ul><li><strong>Error Logging:</strong> Structured client-side error capture with Cloud Logging integration</li><li><strong>Feedback Widget:</strong> In-app mechanism for users to report bugs with context</li><li><strong>Support Documentation:</strong> User-facing FAQ and troubleshooting guides</li><li><strong>Admin Tools:</strong> Basic admin dashboard for user management and debugging</li></ul><hr><h2 id="p1-—-core-engine" tabindex="-1">P1 — Core Engine <a class="header-anchor" href="#p1-—-core-engine" aria-label="Permalink to &quot;P1 — Core Engine&quot;">​</a></h2><h3 id="character-manager-ui" tabindex="-1">Character Manager UI <a class="header-anchor" href="#character-manager-ui" aria-label="Permalink to &quot;Character Manager UI&quot;">​</a></h3><p>Complete the <code>CharacterManager.tsx</code> UI for the &quot;Cast&quot; system — assign specific Google Cloud TTS voices (WaveNet, Standard, Neural2) to characters in scripts.</p><h3 id="workflow-optimizations" tabindex="-1">Workflow Optimizations <a class="header-anchor" href="#workflow-optimizations" aria-label="Permalink to &quot;Workflow Optimizations&quot;">​</a></h3><ul><li><strong>1-Click Import:</strong> Combine script import and storyboard structure into a single step for faster processing.</li></ul><h3 id="background-video-rendering" tabindex="-1">Background Video Rendering <a class="header-anchor" href="#background-video-rendering" aria-label="Permalink to &quot;Background Video Rendering&quot;">​</a></h3><p>Move <code>exportVideo</code> from browser canvas to a backend Cloud Run service using FFmpeg. Prevents browser crashes on large projects.</p><h3 id="thumbnail-preview-selection" tabindex="-1">Thumbnail Preview &amp; Selection <a class="header-anchor" href="#thumbnail-preview-selection" aria-label="Permalink to &quot;Thumbnail Preview &amp; Selection&quot;">​</a></h3><p>Generate 3–4 thumbnail options, preview in Studio, select favourite before pushing to YouTube.</p><h3 id="math-equation-handling" tabindex="-1">Math Equation Handling <a class="header-anchor" href="#math-equation-handling" aria-label="Permalink to &quot;Math Equation Handling&quot;">​</a></h3><p>Parse math equations into plain English for Text-to-Speech (e.g. &#39;$x^2$&#39; to &#39;x squared&#39;) but preserve LaTeX/symbols visually for Vertex AI image generation prompts to display proper equations.</p><hr><h2 id="p2-—-technical-debt" tabindex="-1">P2 — Technical Debt <a class="header-anchor" href="#p2-—-technical-debt" aria-label="Permalink to &quot;P2 — Technical Debt&quot;">​</a></h2><ul><li><strong>Deep Cloud Storage Cleanup:</strong> Firestore trigger to auto-delete GCS audio/video/thumbnails when a Script or Project is deleted (prevents phantom storage costs)</li><li><strong>Audio Refresh Feedback:</strong> Visual spinner on timeline when an expired audio link is being refreshed</li><li><strong>Draft Versioning:</strong> UI to view and revert to older <code>video_drafts</code></li><li><strong>Wake Lock Fallback Warning:</strong> Display a UI warning for browsers that don&#39;t support the experimental <code>navigator.wakeLock</code> API during automation</li><li><strong>Cloud Telemetry Wiring:</strong> Replace mock data in the compiled MCP server with live <code>@google-cloud/logging</code> queries</li><li><strong>Cloud Render Tracking:</strong> Update external cloud renderer to stream granular real-time progress (frame by frame, scene by scene) back to Firestore <code>video_drafts</code> for the UI to display during automation.</li></ul><hr><h2 id="p3-—-advanced-features-long-term" tabindex="-1">P3 — Advanced Features (Long-Term) <a class="header-anchor" href="#p3-—-advanced-features-long-term" aria-label="Permalink to &quot;P3 — Advanced Features (Long-Term)&quot;">​</a></h2><ul><li><strong>AI Script Co-Pilot:</strong> In-editor AI assistant (TipTap + Vertex AI) for &quot;Make it funnier&quot; and 3-act outline generation</li><li><strong>Auto-Captions &amp; Subtitles:</strong> Speech-to-Text timestamps burned as animated text overlays via FFmpeg</li><li><strong>Multi-Platform Export (Shorts/Reels):</strong> 9:16 aspect ratio toggle with intelligent subject cropping</li><li><strong>Smart Background Music:</strong> Music generation API matching the Vibe Map, with automatic audio ducking</li><li><strong>Predefined Style Templates:</strong> Provide visual style templates for image/video generation and allow users to configure custom brand guidelines</li><li><strong>A/B Testing Automation:</strong> Daily Cloud Function to check YouTube Analytics CTR and auto-swap titles/thumbnails</li></ul><hr><h2 id="p4-—-agentic-efficiency-ongoing" tabindex="-1">P4 — Agentic Efficiency (Ongoing) <a class="header-anchor" href="#p4-—-agentic-efficiency-ongoing" aria-label="Permalink to &quot;P4 — Agentic Efficiency (Ongoing)&quot;">​</a></h2><ul><li><strong>Genkit Dotprompt Modularization:</strong> Move remaining hardcoded LLM prompts into <code>.prompt</code> files with Zod structured output</li></ul><hr><h2 id="📋-cross-references" tabindex="-1">📋 Cross-References <a class="header-anchor" href="#📋-cross-references" aria-label="Permalink to &quot;📋 Cross-References&quot;">​</a></h2><ul><li><strong>Active work items:</strong> <a href="./implementation_status.html">implementation_status.md</a></li><li><strong>Completed features archive:</strong> <a href="./changelog.html">changelog.md</a></li></ul>',32)])])}const p=a(i,[["render",n]]);export{h as __pageData,p as default};
